let dbPath = "";
let db;
let assetsDir = "";
let imagesDir = "";
function getDbConfigPath() {
  return path.join(electron.app.getPath("userData"), "db-config.json");
}
function readDbConfig() {
  try {
    const raw = fs.readFileSync(getDbConfigPath(), "utf-8");
    const cfg = JSON.parse(raw);
    if (cfg.dbPath && typeof cfg.dbPath === "string" && cfg.dbPath.trim()) {
      const p = cfg.dbPath.trim();
      try {
        if (fs.statSync(p).isDirectory()) return path.join(p, "capybara.db");
      } catch {
      }
      return p;
    }
  } catch {
  }
  return null;
}
function writeDbConfig(dbPathValue) {
  const p = getDbConfigPath();
  if (!dbPathValue.trim()) {
    try {
      fs.unlinkSync(p);
    } catch {
    }
  } else {
    fs.writeFileSync(p, JSON.stringify({ dbPath: dbPathValue.trim() }, null, 2), "utf-8");
  }
}
function setCustomDbPath(newPath) {
  if (!newPath.trim()) {
    writeDbConfig("");
    return { ok: true };
  }
  const resolved = path.resolve(newPath.trim());
  const parent = path.dirname(resolved);
  if (!fs.existsSync(parent)) {
    return { ok: false, error: `目录不存在：${parent}` };
  }
  try {
    fs.accessSync(parent, fs.constants.W_OK);
  } catch {
    return { ok: false, error: `目录不可写：${parent}` };
  }
  writeDbConfig(resolved);
  return { ok: true };
}
function getCustomDbPath() {
  return readDbConfig() ?? "";
}
function getAssetsDir() {
  return assetsDir;
}
function getImagesDir() {
  return imagesDir;
}
function getDb() {
  return db;
}
function clearFeedCache(id) {
  db.prepare("UPDATE feeds SET etag = '', last_modified = '' WHERE id = ?").run(id);
}
function clearAllFeedCache() {
  db.prepare("UPDATE feeds SET etag = '', last_modified = ''").run();
}
function defaultDbPath() {
  return path.join(electron.app.getPath("userData"), "capybara.db");
}
function legacyDbCandidates() {
  return [
    path.join(electron.app.getPath("userData"), "readflow.db"),
    // v0.7.34 改名前
    path.join(electron.app.getPath("userData"), "readflow", "readflow.db"),
    // v0.7.33 嵌套
    path.join(electron.app.getPath("userData"), "capybara", "capybara.db")
    // 历史嵌套同名
  ];
}
function getDbFile() {
  if (!dbPath) {
    try {
      dbPath = defaultDbPath();
    } catch {
    }
  }
  return dbPath;
}
function countItems(p) {
  try {
    const d = new node_sqlite.DatabaseSync(p);
    const n = d.prepare("SELECT COUNT(*) c FROM items").get().c;
    d.close();
    return n;
  } catch {
    return -1;
  }
}
function migrateLegacyDatabase(canonical) {
  const canonN = countItems(canonical);
  if (canonN > 0) return;
  let best = "";
  let bestN = 0;
  for (const cand of legacyDbCandidates()) {
    if (cand === canonical || !fs.existsSync(cand)) continue;
    const n = countItems(cand);
    if (n > bestN) {
      bestN = n;
      best = cand;
    }
  }
  if (!best) return;
  const dir = path.dirname(canonical);
  fs.mkdirSync(dir, { recursive: true });
  for (const ext of ["", "-wal", "-shm"]) {
    const src = best + ext;
    if (fs.existsSync(src)) {
      try {
        fs.copyFileSync(src, canonical + ext);
      } catch {
      }
    }
  }
  const copiedN = countItems(canonical);
  if (copiedN >= bestN) {
    for (const ext of ["", "-wal", "-shm"]) {
      try {
        fs.renameSync(best + ext, best + ext + ".migrated");
      } catch {
      }
    }
    console.log(`[initDb] 已从历史旧路径迁移数据库：${best} -> ${canonical}（${copiedN} 条条目）`);
  } else {
    console.error(`[initDb] 旧库迁移校验失败，已保留原文件：${best}`);
  }
}
function checkpoint() {
  try {
    db.exec("PRAGMA wal_checkpoint(TRUNCATE)");
  } catch {
  }
}
let walTimer = null;
const WAL_CHECKPOINT_INTERVAL = 30 * 60 * 1e3;
const WAL_SIZE_THRESHOLD = 10 * 1024 * 1024;
function startWalCheckpoint() {
  walTimer = setInterval(() => {
    try {
      const walFile = dbPath.replace(/\.db$/, ".db-wal");
      const stat = fs.statSync(walFile);
      if (stat.size > WAL_SIZE_THRESHOLD) {
        console.log(`[db] WAL 文件 ${(stat.size / 1024 / 1024).toFixed(1)}MB，执行 checkpoint`);
        checkpoint();
      }
    } catch {
    }
  }, WAL_CHECKPOINT_INTERVAL);
}
function stopWalCheckpoint() {
  if (walTimer) {
    clearInterval(walTimer);
    walTimer = null;
  }
}
function relocateLegacyDataDir(userData) {
  const legacy = path.join(userData, "readflow");
  if (!fs.existsSync(legacy) || !fs.statSync(legacy).isDirectory()) return;
  for (const name of ["images", "backups", "board-assets"]) {
    const src = path.join(legacy, name);
    const dst = path.join(userData, name);
    if (fs.existsSync(src) && !fs.existsSync(dst)) {
      try {
        fs.renameSync(src, dst);
      } catch {
        try {
          fs.cpSync(src, dst, { recursive: true });
          fs.rmSync(src, { recursive: true, force: true });
        } catch {
        }
      }
    }
  }
  try {
    for (const f of fs.readdirSync(legacy)) {
      if (f.includes(".migrated")) {
        const s = path.join(legacy, f);
        const d = path.join(userData, "legacy-" + f);
        if (!fs.existsSync(d)) {
          try {
            fs.renameSync(s, d);
          } catch {
          }
        }
      }
    }
  } catch {
  }
  try {
    if (fs.readdirSync(legacy).length === 0) fs.rmdirSync(legacy);
  } catch {
  }
}
function initDb() {
  const customPath = readDbConfig();
  const defaultDir = electron.app.getPath("userData");
  let baseDir;
  if (customPath) {
    dbPath = customPath;
    baseDir = path.dirname(customPath);
    console.log("[initDb] 使用自定义数据库路径：", dbPath);
  } else {
    baseDir = defaultDir;
    dbPath = path.join(baseDir, "capybara.db");
    console.log("[initDb] 使用默认数据库路径：", dbPath);
  }
  fs.mkdirSync(path.join(baseDir, "images"), { recursive: true });
  fs.mkdirSync(path.join(baseDir, "backups"), { recursive: true });
  if (!customPath) {
    try {
      migrateLegacyDatabase(dbPath);
    } catch (e) {
      console.error("[initDb] 迁移旧库失败：", e.message);
    }
    try {
      relocateLegacyDataDir(defaultDir);
    } catch (e) {
      console.error("[initDb] 迁移数据子目录失败：", e.message);
    }
  }
  assetsDir = path.join(baseDir, "board-assets");
  fs.mkdirSync(assetsDir, { recursive: true });
  imagesDir = path.join(baseDir, "images");
  db = new node_sqlite.DatabaseSync(dbPath);
  db.exec("PRAGMA journal_mode = WAL");
  console.log("[initDb] 数据库文件：", dbPath);
  console.log("[initDb] 数据目录：", baseDir);
  migrate();
  startWalCheckpoint();
}
